  /deep/.ivu-tabs-context-menu{
    width 0;
    height 0;
  }
	.ivu-menu-horizontal .ivu-menu-item{
		padding 0 10px;
	}
  .i-layout-menu-head {
    min-width: 0;
  }
  .ivu-tabs {
    color: rgba(255, 255, 255, 0.7);
  }
  >>>.ivu-tabs-bar {
    border-bottom: 0;
    margin-bottom: 0;
  }
  >>>.ivu-tabs-nav .ivu-tabs-tab {
    height: 66px;
    padding: 0 10px;
    line-height: 66px;
  }
  >>>.ivu-tabs-nav .ivu-tabs-tab-active {
    font-weight: 800;
    color: #FFFFFF;
  }
  >>>.ivu-tabs-ink-bar {
    background-color: #FFFFFF;
    bottom: 2px;
  }
  >>>.ivu-tabs-nav .ivu-tabs-tab:hover {
    font-weight: 800;
    color: #FFFFFF !important;
  }
  >>>.ivu-tabs-nav .ivu-tabs-tab:active {
    font-weight: 800;
    color: #FFFFFF !important;
  }
  >>>.ivu-tabs-nav-prev, >>>.ivu-tabs-nav-next {
    z-index: 2;
    line-height: 64px;
  }
